// aprobat prin OM 5420/04.07.2024, conform OMEN 3393/28.02.2017,
// ISBN 978-630-342-037-0.
//
// Aici este recapitularea inițială, Unitatea 1 până la capăt,
// Unitatea 2, Punți între lumi, până la capăt, Unitatea 3,
// Tărâmul sentimentelor, până la capăt, Unitatea 4,
// Lumea teatrului, până la capăt, și Unitatea 5,
// Călător prin lume, până la capăt. Restul clasei a VII-a
// și clasa a VIII-a nu sunt încă aici.
// Nu copiem fragmente, poezii, citate sau anunțuri cuvânt cu cuvânt.
// Scena de care are nevoie copilul este scrisă în lecție.
// Grilele de punctaj și fișa de observare nu sunt lecții.

function lesson(id, title, block) {
  const example = String(block.example || '').replace(/^Exemplu lucrat:\s*/i, '');
  const platter = [block.theory, `Exemplu lucrat: ${example}`, block.tryThis, block.recap].join('\n\n');
  return {
    id,
    title,
    platter,
    theory: block.theory,
    example,
    tryThis: block.tryThis,
    recap: block.recap
  };
}

